use sqlx::{sqlite::{SqlitePoolOptions,SqliteConnectOptions},Row};
use video_kadr_backend::{db::Db,domain::composition::Composition};
#[tokio::test]
async fn legacy_video_cache_rows_gain_rvm_identity_without_losing_provenance(){
 let dir=tempfile::tempdir().unwrap();let db=Db::open(dir.path()).await.unwrap();let space=db.create_space("owner","Legacy").await.unwrap();let project=db.create_space_composition_project("Legacy",&serde_json::to_value(Composition::new(Default::default())).unwrap(),&[],"owner",&space.id).await.unwrap();drop(db);
 let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(dir.path().join("app.db")).foreign_keys(true)).await.unwrap();
 sqlx::query("DROP TABLE concat_video_project_caches").execute(&pool).await.unwrap();sqlx::query("CREATE TABLE concat_video_project_caches(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,source_id TEXT NOT NULL,video_hash TEXT NOT NULL,runtime_hash TEXT NOT NULL,manifest_hash TEXT NOT NULL,generation TEXT NOT NULL,FOREIGN KEY(project_id) REFERENCES composition_projects(id) ON DELETE CASCADE)").execute(&pool).await.unwrap();let generation=format!("concat-video-cache-{}",uuid::Uuid::new_v4());sqlx::query("INSERT INTO concat_video_project_caches VALUES(?,?,?,?,?,?,?)").bind("legacy").bind(&project.id).bind("raw").bind("a".repeat(64)).bind("b".repeat(64)).bind("c".repeat(64)).bind(&generation).execute(&pool).await.unwrap();pool.close().await;
 let (first,second)=tokio::join!(Db::open(dir.path()),Db::open(dir.path()));drop(first.unwrap());drop(second.unwrap());let reopened=Db::open(dir.path()).await.unwrap();drop(reopened);
 let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(dir.path().join("app.db"))).await.unwrap();let row=sqlx::query("SELECT project_id,source_id,video_hash,runtime_hash,manifest_hash,generation,model_hash FROM concat_video_project_caches WHERE id='legacy'").fetch_one(&pool).await.unwrap();assert_eq!(row.get::<String,_>("project_id"),project.id);assert_eq!(row.get::<String,_>("source_id"),"raw");assert_eq!(row.get::<String,_>("video_hash"),"a".repeat(64));assert_eq!(row.get::<String,_>("runtime_hash"),"b".repeat(64));assert_eq!(row.get::<String,_>("manifest_hash"),"c".repeat(64));assert_eq!(row.get::<String,_>("generation"),generation);assert_eq!(row.get::<String,_>("model_hash"),video_kadr_backend::services::local_person::MODEL_HASH);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT COUNT(*) FROM concat_video_project_caches").fetch_one(&pool).await.unwrap(),1);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name='concat_video_project_cache_model_lookup'").fetch_one(&pool).await.unwrap(),1);
}
